def minimumLength(s):
    # Create a list of all possible substrings of "AB" and "CD"
    substrings = ["AB", "CD"]
    # Create a list of all possible substrings of s
    all_substrings = [s[i:j] for i in range(len(s)) for j in range(i+1, len(s)+1)]
    # Create a set to store all substrings that can be removed
    removed_substrings = set()
    # Iterate over all substrings of s
    for sub in all_substrings:
        # Check if the substring is in the list of substrings of "AB" or "CD"
        if sub in substrings:
            # If it is, add it to the set of removed substrings
            removed_substrings.add(sub)
    # Iterate over all substrings of s
    for sub in all_substrings:
        # If the substring is not in the set of removed substrings, remove it
        if sub not in removed_substrings:
            s = s.replace(sub, "")
    # Return the length of the resulting string
    return len(s)

def punishmentNumber(n):
    punishment_number = 0
    for i in range(1, n+1):
        if i * i <= n:
            for j in range(1, i+1):
                if i * i % j == 0:
                    punishment_number += i * i // j
    return punishment_number

