    for i in range(n):
        dp[0][i] = 1 if s[i] == s[i-1] else 0
    for i in range(1, k):
        for j in range(n):
            if j - i >= 0:
                dp[i][j] = dp[i-1][j] + 1 if s[j] != s[j-i] else dp[i-1][j-i]
            else:
                dp[i][j] = dp[i-1][j] + 1 if s[j] != s[j-i] else dp[i-1][j-i]
    return min(dp[k-1])

