def kthDistinct(coordinates, k):
    def xor_sum(x, y):
        return x ^ y

    def count_pairs(x, y, k):
        count = 0
        for i in range(len(coordinates)):
            for j in range(i + 1, len(coordinates)):
                if xor_sum(x, coordinates[i][0]) == xor_sum(y, coordinates[j][0]) and xor_sum(x, coordinates[i][1]) == xor_sum(y, coordinates[j][1]):
                    count += 1
        return count

    return count_pairs(0, 0, k)

def maxSum(nums, m, k):
    n = len(nums)
    if n < k:
        return 0

    # Create a dictionary to store the frequency of each element
    freq = {}
    for i in range(n):
        if nums[i] in freq:
            freq[nums[i]] += 1
        else:
            freq[nums[i]] = 1

    # Create a list to store the sum of all subarrays of size k
    sums = []

    # Traverse through the array
    for i in range(n - k + 1):
        # Calculate the sum of the current subarray
        subarray_sum = sum(nums[i:i+k])

        # If the subarray is almost unique, add it to the list of sums
        if len(set(nums[i:i+k])) == m:
            sums.append(subarray_sum)

    # Find the maximum sum from the list of sums
    max_sum = max(sums)

    return max_sum

