def numWays(s, t, k):
    n = len(s)
    mod = 10**9 + 7
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for gap in range(1, n):
        for i in range(n-gap):
            j = i + gap
            if s[i] == t[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = (dp[i+1][j] + dp[i][j-1]) % mod
    return dp[0][n-1]

def minOperations(nums, target):
    target = target // 2
    nums.sort()
    n = len(nums)
    dp = [float('inf')] * (target + 1)
    dp[0] = 0
    for i in range(n):
        for j in range(target, nums[i] - 1, -1):
            dp[j] = min(dp[j], dp[j - nums[i]] + 1)
    return dp[target] if dp[target] != float('inf') else -1

def productMatrix(grid):
    n, m = len(grid), len(grid[0])
    p = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            p[i][j] = grid[i][j]
            for k in range(m):
                if k != j:
                    p[i][j] *= grid[i][k]
            for k in range(n):
                if k != i:
                    p[i][j] *= grid[k][j]
    for i in range(n):
        for j in range(m):
            p[i][j] %= 12345
    return p

def minCost(s1, s2, x):
    n = len(s1)
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(n + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            else:
                dp[i][j] = min(dp[i - 1][j - 1] + (s1[i - 1] != s2[j - 1]) * x, dp[i - 1][j] + x, dp[i][j - 1] + x)
    return dp[n][n] if dp[n][n] != float('inf') else -1

