def solve(N1, N2, M):
    # Create a graph with N1+N2 vertices
    graph = [[0]*(N1+N2+1) for _ in range(N1+N2+1)]

    # Add edges according to the given input
    for i in range(M):
        u, v = map(int, input().split())
        graph[u][v] = graph[v][u] = 1

    # Find the minimum length path between 1 and (N1+N2)
    def find_min_path(u, v):
        if graph[u][v] == 1:
            return 0
        if graph[u][v] == 0:
            return -1
        path = 1
        while graph[u][v] == 0:
            u, v = v, u
            path += 1
        return path

    # Find the maximum possible d
    max_d = 0
    for u in range(1, N1+1):
        for v in range(N1+1, N1+N2+1):
            d = find_min_path(u, v)
            if d > max_d:
                max_d = d
    return max_d

