def count_parenthesis_strings(s):
    # Initialize the count of valid parenthesis strings
    count = 0

    # Iterate over all possible positions of ? in S
    for i in range(len(s)):
        # If the current position is a ?, we can replace it with either ( or )
        for j in range(2):
            # Create a new string by replacing the current ? with either ( or )
            new_s = s[:i] + j + s[i+1:]

            # Check if the new string is a valid parenthesis string
            if is_valid_parenthesis_string(new_s):
                # Increment the count of valid parenthesis strings
                count += 1

    # Return the count of valid parenthesis strings modulo 998244353
    return count % 998244353

def is_valid_parenthesis_string(s):
    # Check if the string is empty
    if not s:
        return True

    # Check if the string contains only ( or )
    if s[0] == '(' and s[-1] == ')':
        return is_valid_parenthesis_string(s[1:-1])
    else:
        return False

