def solve(n):
    # Create a graph with n vertices
    graph = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            graph[i][j] = graph[j][i] = min(graph[i][j], D[i][j])

    # Find the maximum weight spanning tree
    def dfs(u, parent):
        for v in range(n):
            if graph[u][v] > 0 and v != parent:
                dfs(v, u)
                graph[u][v] = graph[v][u] = max(graph[u][v], graph[u][parent] + graph[v][parent])

    # Find the maximum weight spanning tree
    dfs(0, -1)

    # Find the maximum weight edge in the spanning tree
    max_weight = 0
    for i in range(n):
        for j in range(i+1, n):
            if graph[i][j] > max_weight:
                max_weight = graph[i][j]

    return max_weight

