def solve(N, K, P, C, A):
    # Initialize the cost to 0
    cost = 0

    # Iterate over all development plans
    for i in range(1, N+1):
        # Check if the current development plan can be executed
        if C[i-1] <= P:
            # Check if the current development plan can increase the value of at least one parameter to at least P
            for j in range(1, K+1):
                if A[i-1][j-1] >= P:
                    # If the current development plan can increase the value of at least one parameter to at least P,
                    # add the cost of executing the development plan to the total cost
                    cost += C[i-1]
                    # Update the value of the parameter to at least P
                    A[i-1][j-1] = P
                    # If the value of the parameter to at least P is already at least P,
                    # break the loop to avoid unnecessary execution of the development plan
                    if A[i-1][j-1] >= P:
                        break

    # If the company can achieve the goal, return the minimum total cost required to achieve the goal
    if cost <= P:
        return cost
    # If the company cannot achieve the goal, return -1
    else:
        return -1

