import math

def solve(H, W, S):
    # Create a graph where each cell is a node and an edge exists between two nodes if they are adjacent
    graph = [[0]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                graph[i][j] = 1
            else:
                graph[i][j] = 0

    # Perform DFS to count the number of connected components
    def dfs(i, j):
        if 0 <= i < H and 0 <= j < W and graph[i][j] == 1:
            graph[i][j] = 0
            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                dfs(i + di, j + dj)

    # Count the number of connected components
    connected_components = 0
    for i in range(H):
        for j in range(W):
            if graph[i][j] == 1:
                dfs(i, j)
                connected_components += 1

    # Calculate the expected value
    expected_value = connected_components
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                expected_value *= 2

    # Calculate the expected value modulo 998244353
    expected_value %= 998244353

    return expected_value

