def arrange_parts():
    N = int(input())
    if N % 2 != 1:
        return "Error: N must be an odd number."
    if N > 45:
        return "Error: N must be less than or equal to 45."

    grid = [[0 for _ in range(N)] for _ in range(N)]
    dragon = [i for i in range(1, N**2)]
    dragon.sort()

    for i in range(N):
        for j in range(N):
            if i == N//2 and j == N//2:
                grid[i][j] = 1
            else:
