def minBoxes(apple, capacity):
    n = len(apple)
    m = len(capacity)
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if apple[i - 1] <= capacity[j - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1)
            if apple[i - 1] > capacity[j - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + 1)
    return dp[n][m]

