    for i in range(n + 1):
        dp[i][0] = 0
    for i in range(1, n + 1):
        for j in range(1, cost2 + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums[i - 1]] + cost1)
    return dp[n][cost2] % (10**9 + 7)

def can_make_square(grid):
    def dfs(i, j, color):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] != color:
            return False
        grid[i][j] = '.'
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            if dfs(i + di, j + dj, color):
                return True
        grid[i][j] = color
        return False

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'B':
                if dfs(i, j, 'W'):
                    return True
    return False

def countRightTriangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(i+1, len(grid)):
            for k in range(j+1, len(grid)):
                if grid[i][j] == 1 and grid[j][k] == 1 and grid[k][i] == 1:
                    count += 1
    return count

def stableArrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [0] * (one + 1)
    dp[0] = 1
    for i in range(zero + 1):
        dp[i] = (dp[i] + dp[i - 1]) % MOD
    for i in range(one + 1):
        dp[i] = (dp[i] + dp[i - 1]) % MOD
    for i in range(limit + 1):
        dp[i] = (dp[i] + dp[i - 1]) % MOD
    return sum(dp)

def isSpecial(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def sumOfDigitDifferences(nums):
    total_sum = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            diff = len(set(str(nums[i])).intersection(str(nums[j])))
            total_sum += diff
    return total_sum

def countGoodPairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % k == 0 and nums2[j] % k == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        if i == 0:
            comp += str(len(word)) + word[0]
        else:
            if word[i] == word[i-1]:
                comp += str(len(word) - i) + word[i]
            else:
                comp += str(len(word) - i) + word[i]
    return comp

def sumOfSubsequenceWiseProducts(nums, queries):
    mod = 10**9 + 7
    n = len(nums)
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for l in range(1, n):
        for i in range(n-l):
            j = i + l
            dp[i][j] = dp[i][j-1]
            for k in range(i, j):
                dp[i][j] = (dp[i][j] + dp[i][k] * dp[k+1][j]) % mod
    ans = 0
    for i, j in queries:
        ans = (ans + dp[i-1][j-1]) % mod
    return ans

def minPartitions(s):
    max_val = 0
    for char in s:
        if char.isdigit():
            max_val = max(max_val, int(char))
    return max_val

def big_nums(queries):
    big_nums = [1]
    for i in range(1, 1000000):
        big_nums.append(big_nums[-1] * 2)
    return [big_nums[queries[i][0]] * big_nums[queries[i][0] + 1] * ... * big_nums[queries[i][1]] % queries[i][2] for i in range(len(queries))]

def xor_twice(nums):
    xor = 0
    for num in nums:
        xor ^= num
    return xor

def findSubarray(nums, queries, x):
    result = []
    for i in range(len(queries)):
        index = -1
        for j in range(len(nums)):
            if nums[j] == x:
                index = j
                break
        if index != -1:
            result.append(index)
        else:
            result.append(-1)
    return result
